export const SuggestedTrackStatus = defineEnum({
  NeedsEvidence: "needs_evidence",
  EvidenceSubmitted: "evidence_submitted",
  OperatorReview: "operator_review",
  SourceBacked: "source_backed",
  Retired: "retired",
} as const);

export type SuggestedTrackStatus = EnumValue<typeof SuggestedTrackStatus>;

import { SuggestedTrackStatus, type SuggestedTrackStatusValue } from "../enums/suggested-track-status";

export const newSuggestionNeedsEvidence = (
  status: SuggestedTrackStatusValue,
): boolean => status === SuggestedTrackStatus.NeedsEvidence;

import { newSuggestionNeedsEvidence } from "../rules/new-suggestion-needs-evidence";

if (!newSuggestionNeedsEvidence(track.status)) {
  throw new Error("New suggestions must need evidence");
}
